svg.script:
(function(){
  // Set metadata on the outer SVG document itself, not just the packed iframe.
  try { document.title = "BlobeGames II"; } catch (e) {}

  try {
    var old = document.getElementById("parentFavicon");
    if (old && old.parentNode) old.parentNode.removeChild(old);

    var icon = document.createElementNS("http://www.w3.org/1999/xhtml", "link");
    icon.setAttribute("id", "parentFavicon");
    icon.setAttribute("rel", "icon");
    icon.setAttribute("type", "image/png");
    icon.setAttribute("href", "data:image/png;base64,");
    document.documentElement.appendChild(icon);
  } catch (e) {}
})();

(function(){
  if (document.documentElement.namespaceURI !== "http://www.w3.org/2000/svg") return;
  var XHTML = "http://www.w3.org/1999/xhtml";
  var SVG = "http://www.w3.org/2000/svg";
  var svgTags = {svg:1, path:1, circle:1, rect:1, g:1, defs:1, use:1, text:1,
                 line:1, ellipse:1, polygon:1, polyline:1, filter:1, mask:1};
  document.createElement = function(tag, opts){
    var name = String(tag).toLowerCase();
    if (svgTags[name]) return document.createElementNS(SVG, name, opts);
    return document.createElementNS(XHTML, name, opts);
  };
})();

(function(){
  if (document.documentElement.namespaceURI !== "http://www.w3.org/2000/svg") return;
  var root = document.getElementById("app");
  if (!root) return;
  try {
    Object.defineProperty(document, "body", {
      configurable: true, get: function(){ return root; }
    });
  } catch (e) {}
  try {
    if (!document.head) {
      Object.defineProperty(document, "head", {
        configurable: true,
        get: function(){ return document.documentElement; }
      });
    }
  } catch (e) {}
})();

(function(){
  if (document.documentElement.namespaceURI !== "http://www.w3.org/2000/svg") return;
  var proto = (typeof HTMLElement !== "undefined" && HTMLElement.prototype) || Element.prototype;
  Object.defineProperty(proto, "innerHTML", {
    configurable: true,
    get: function(){
      var out = "", ser = new XMLSerializer(), n = this.firstChild;
      while (n) { out += (n.nodeType === 3 ? n.nodeValue : ser.serializeToString(n)); n = n.nextSibling; }
      return out;
    },
    set: function(str){
      while (this.firstChild) this.removeChild(this.firstChild);
      var parsed = new DOMParser().parseFromString("<!doctype html><body>" + str, "text/html");
      var doc = this.ownerDocument;
      for (var k = parsed.body.firstChild; k; k = k.nextSibling) {
        this.appendChild(doc.importNode(k, true));
      }
    }
  });
})();

(function(){
  var A = window.__packAssets || {};
  var cache = {};
  var BASE = "https://cdn.jsdelivr.net/gh/ioBybbolB/ioBybbolB.github.io/";
  function key(u){
    if (typeof u !== "string" || !u) return null;
    var s = u.split("?")[0].split("#")[0];
    if (BASE && s.indexOf(BASE) === 0) {
      s = s.slice(BASE.length);
    } else if (/^[a-z][a-z0-9+.-]*:/i.test(s) || s.indexOf("//") === 0) {
      return null;
    }
    s = s.replace(/^\.?\//, "");
    while (s.indexOf("../") === 0) s = s.slice(3);
    return Object.prototype.hasOwnProperty.call(A, s) ? s : null;
  }
  window.__packBlob = function(u){
    var k = key(u);
    if (k === null) return null;
    if (cache[k]) return cache[k];
    var v = A[k], cut = v.indexOf("|");
    var mime = v.slice(0, cut), b = atob(v.slice(cut + 1));
    var arr = new Uint8Array(b.length);
    for (var i = 0; i < b.length; i++) arr[i] = b.charCodeAt(i);
    cache[k] = URL.createObjectURL(new Blob([arr], {type: mime}));
    return cache[k];
  };
})();

(function(){
  var BASE = "https://cdn.jsdelivr.net/gh/ioBybbolB/ioBybbolB.github.io/";
  if (!BASE && !window.__packBlob) return;
  function abs(u){
    if (typeof u !== "string" || !u) return u;
    if (window.__packBlob) {
      var hit = window.__packBlob(u);
      if (hit) return hit;
    }
    if (!BASE) return u;
    if (/^(?:[a-z][a-z0-9+.-]*:|\/\/|#)/i.test(u)) return u;
    try { return new URL(u, BASE).href; } catch (e) { return u; }
  }
  var xo = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function(m, u){
    arguments[1] = abs(u);
    return xo.apply(this, arguments);
  };
  if (window.fetch) {
    var of = window.fetch;
    window.fetch = function(input, init){
      if (typeof input === "string") input = abs(input);
      else if (input && input.url) input = new Request(abs(input.url), input);
      return of.call(this, input, init);
    };
  }
  ["HTMLImageElement", "HTMLMediaElement", "HTMLScriptElement",
   "HTMLSourceElement", "HTMLTrackElement"].forEach(function(n){
    var C = window[n];
    if (!C) return;
    var d = Object.getOwnPropertyDescriptor(C.prototype, "src");
    if (!d || !d.set) return;
    Object.defineProperty(C.prototype, "src", {
      configurable: true, enumerable: d.enumerable,
      get: d.get,
      set: function(v){ d.set.call(this, abs(v)); }
    });
  });
})();

(function(){
  if (document.write && document.documentElement.namespaceURI === "http://www.w3.org/2000/svg") {
    document.write = function(){
      var root = document.getElementById(window.__packRoot || "app");
      if (root) root.innerHTML = (root.innerHTML || "") + Array.prototype.join.call(arguments, "");
    };
    document.writeln = document.write;
  }
})();

window.__packRoot='app';
(function(){
  var XHTML = "http://www.w3.org/1999/xhtml";
  var root = document.getElementById("app");
  if (!root) return;

  root.style.width = "100%";
  root.style.height = "100%";
  root.style.margin = "0";
  root.style.padding = "0";
  root.style.overflow = "hidden";
  root.style.background = "#000";

  var frame = document.createElementNS(XHTML, "iframe");
  frame.setAttribute("id", "packFrame");
  frame.setAttribute("frameborder", "0");
  frame.style.display = "block";
  frame.style.width = "100%";
  frame.style.height = "100%";
  frame.style.border = "0";
  frame.style.margin = "0";
  frame.style.padding = "0";
  frame.style.background = "#000";

  var packed = window.__packBlob && window.__packBlob("index.html");
  frame.setAttribute("src", packed || "about:blank");
  root.appendChild(frame);
})();
